<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, BarChart3, Building2, CalendarDays, CheckCircle2, ClipboardList, CreditCard, Filter, LogOut, Menu, Radio, RefreshCw, Search, ShieldAlert, ShieldCheck, TriangleAlert, Users, X } from 'lucide-vue-next'
import { supabase } from './lib/supabase'

type Overview = { tenants: number; users: number; pools: number; open_pools: number; matches: number; results: number; audit_events_24h: number; pending_plan_requests: number }
type Tenant = { tenant_id: string; name: string; plan_code: string; pools: number; participants: number; created_at: string }
type Request = { id: string; tenant_name: string; offer_code: string; status: string; requested_at: string }
type Offer = { offer_code: string; plan_code: string; scope: string; price_minor: number; currency: string; billing_period: 'month' | 'year' | 'one_time'; benefits: string[]; is_public: boolean }
type ConsoleUser = { profile_id: string; display_name: string; memberships: number; pools: number; created_at: string }
type SportOperation = { tenant_name: string; tournament_name: string; match_id: string; home_team: string; away_team: string; starts_at: string; status: string; result: string | null }
type ActivityEvent = { source: string; tenant_name: string | null; action: string; entity_type: string; created_at: string }
type Monitor = { matches_live: number; matches_next_24h: number; unread_notifications: number; catalog_jobs_failed_24h: number; fixture_sync_events_24h: number }
type GrowthMetrics = { active_users_now: number; active_users_24h: number; new_users_7d: number; new_tenants_30d: number; plan_requests_30d: number; client_errors_24h: number }
type LiveUser = { display_name: string; last_seen_at: string; route: string | null; events_24h: number }
type ErrorLog = { kind: string; name: string; message: string; route: string | null; occurrences: number; latest_at: string }

const CONTROL_EMAIL = 'developer.gruposaysil@gmail.com'
const menu = [
  { key: 'overview', label: 'Centro de control', icon: Activity }, { key: 'analytics', label: 'Analítica y KPIs', icon: BarChart3 },
  { key: 'tenants', label: 'Clientes', icon: Building2 }, { key: 'users', label: 'Usuarios', icon: Users },
  { key: 'sports', label: 'Ligas y partidos', icon: ClipboardList }, { key: 'requests', label: 'Solicitudes', icon: CreditCard },
  { key: 'monitor', label: 'Monitor en vivo', icon: Radio }, { key: 'errors', label: 'Errores y logs', icon: TriangleAlert },
  { key: 'plans', label: 'Catálogo y precios', icon: CreditCard },
]
const active = ref('overview'), mobileOpen = ref(false), loading = ref(true), denied = ref(false), signedIn = ref(false), password = ref(''), message = ref(''), saving = ref(''), refreshing = ref(false)
const tableQuery = ref(''), fromDate = ref(''), toDate = ref(''), statusFilter = ref('all'), quickRange = ref<number | null>(null)
const overview = ref<Overview | null>(null), tenants = ref<Tenant[]>([]), requests = ref<Request[]>([]), offers = ref<Offer[]>([]), users = ref<ConsoleUser[]>([]), sportOperations = ref<SportOperation[]>([]), activity = ref<ActivityEvent[]>([]), monitor = ref<Monitor | null>(null), growth = ref<GrowthMetrics | null>(null), liveUsers = ref<LiveUser[]>([]), errors = ref<ErrorLog[]>([])

const cards = computed(() => overview.value ? [
  { label: 'Organizaciones', value: overview.value.tenants, detail: 'tenants registrados', icon: Building2 }, { label: 'Usuarios', value: overview.value.users, detail: 'perfiles de plataforma', icon: Users },
  { label: 'Quinielas activas', value: overview.value.open_pools, detail: `${overview.value.pools.toLocaleString('es-PE')} en total`, icon: Activity }, { label: 'Resultados', value: overview.value.results, detail: `${overview.value.matches.toLocaleString('es-PE')} partidos`, icon: CheckCircle2 },
] : [])
const signals = computed(() => overview.value ? [{ label: 'Eventos administrativos', value: overview.value.audit_events_24h, note: 'registrados en las últimas 24 h' }, { label: 'Solicitudes pendientes', value: overview.value.pending_plan_requests, note: 'pendientes de revisión manual' }, { label: 'Superficie protegida', value: '100%', note: 'lecturas globales mediante RPC con guard' }] : [])
const filtersVisible = computed(() => ['tenants', 'users', 'sports', 'requests', 'monitor', 'errors'].includes(active.value))
const statusOptions = computed(() => active.value === 'sports' ? [{ value: 'scheduled', label: 'Programado' }, { value: 'live', label: 'En vivo' }, { value: 'final', label: 'Finalizado' }] : active.value === 'errors' ? [{ value: 'error', label: 'Error' }, { value: 'unhandled-rejection', label: 'Rechazo no controlado' }] : active.value === 'requests' ? [{ value: 'pending', label: 'Pendiente' }] : [])

function isInDateRange(value: string): boolean { const date = new Date(value).getTime(); const start = fromDate.value ? new Date(`${fromDate.value}T00:00:00`).getTime() : Number.NEGATIVE_INFINITY; const end = toDate.value ? new Date(`${toDate.value}T23:59:59.999`).getTime() : Number.POSITIVE_INFINITY; return date >= start && date <= end }
function includesQuery(value: string): boolean { const q = tableQuery.value.trim().toLocaleLowerCase('es-PE'); return !q || value.toLocaleLowerCase('es-PE').includes(q) }
function setQuickRange(days: number | null): void { quickRange.value = days; if (days === null) { fromDate.value = ''; toDate.value = ''; return }; const end = new Date(); const start = new Date(); start.setDate(end.getDate() - (days - 1)); fromDate.value = start.toISOString().slice(0, 10); toDate.value = end.toISOString().slice(0, 10) }
function clearFilters(): void { tableQuery.value = ''; fromDate.value = ''; toDate.value = ''; statusFilter.value = 'all'; quickRange.value = null }
function selectView(key: string): void { active.value = key; mobileOpen.value = false; clearFilters() }

const filteredTenants = computed(() => tenants.value.filter((t) => includesQuery(`${t.name} ${t.plan_code}`) && isInDateRange(t.created_at)))
const filteredUsers = computed(() => users.value.filter((u) => includesQuery(u.display_name) && isInDateRange(u.created_at)))
const filteredSports = computed(() => sportOperations.value.filter((m) => includesQuery(`${m.tenant_name} ${m.tournament_name} ${m.home_team} ${m.away_team}`) && (statusFilter.value === 'all' || m.status === statusFilter.value) && isInDateRange(m.starts_at)))
const filteredRequests = computed(() => requests.value.filter((r) => includesQuery(`${r.tenant_name} ${r.offer_code}`) && (statusFilter.value === 'all' || r.status === statusFilter.value) && isInDateRange(r.requested_at)))
const filteredActivity = computed(() => activity.value.filter((e) => includesQuery(`${e.action} ${e.entity_type} ${e.tenant_name ?? ''}`) && isInDateRange(e.created_at)))
const filteredLiveUsers = computed(() => liveUsers.value.filter((u) => includesQuery(`${u.display_name} ${u.route ?? ''}`) && isInDateRange(u.last_seen_at)))
const filteredErrors = computed(() => errors.value.filter((e) => includesQuery(`${e.kind} ${e.name} ${e.message} ${e.route ?? ''}`) && (statusFilter.value === 'all' || e.kind === statusFilter.value) && isInDateRange(e.latest_at)))

async function load(): Promise<boolean> {
  loading.value = true; message.value = ''; const db = supabase()
  const [{ data: ok, error: roleError }, { data: operator, error: operatorError }] = await Promise.all([db.rpc('is_platform_admin'), db.rpc('is_control_operator')])
  if (roleError || operatorError || !ok || !operator) { denied.value = true; loading.value = false; return false }
  const results = await Promise.all([db.rpc('platform_console_overview'), db.rpc('platform_console_tenants', { p_query: null }), db.rpc('platform_console_plan_requests'), db.rpc('platform_console_offers'), db.rpc('platform_console_users', { p_query: null }), db.rpc('platform_console_sport_operations'), db.rpc('platform_console_activity'), db.rpc('platform_console_monitor'), db.rpc('platform_console_growth_metrics'), db.rpc('platform_console_live_users'), db.rpc('platform_console_error_log')])
  if (results.some((result) => result.error)) message.value = 'No fue posible cargar una parte de la consola. Inténtalo de nuevo.'
  overview.value = (results[0].data ?? null) as Overview | null; tenants.value = (results[1].data ?? []) as Tenant[]; requests.value = (results[2].data ?? []) as Request[]; offers.value = (results[3].data ?? []) as Offer[]; users.value = (results[4].data ?? []) as ConsoleUser[]; sportOperations.value = (results[5].data ?? []) as SportOperation[]; activity.value = (results[6].data ?? []) as ActivityEvent[]; monitor.value = (results[7].data ?? null) as Monitor | null; growth.value = (results[8].data ?? null) as GrowthMetrics | null; liveUsers.value = (results[9].data ?? []) as LiveUser[]; errors.value = (results[10].data ?? []) as ErrorLog[]; loading.value = false; return true
}
async function refresh(): Promise<void> { refreshing.value = true; await load(); refreshing.value = false }
async function saveOffer(offer: Offer): Promise<void> { saving.value = offer.offer_code; const { error } = await supabase().rpc('update_plan_offer', { p_offer_code: offer.offer_code, p_price_minor: offer.price_minor, p_currency: offer.currency, p_billing_period: offer.billing_period, p_benefits: offer.benefits, p_is_public: offer.is_public }); saving.value = ''; message.value = error ? 'No se pudo actualizar la oferta.' : 'Oferta actualizada y auditada.' }
async function signOut(): Promise<void> { await supabase().auth.signOut(); window.location.reload() }
async function signIn(): Promise<void> { message.value = ''; const { error } = await supabase().auth.signInWithPassword({ email: CONTROL_EMAIL, password: password.value }); if (error) { message.value = 'No pudimos iniciar sesión.'; return }; signedIn.value = true; await load() }
onMounted(async () => { const { data } = await supabase().auth.getSession(); const email = data.session?.user.email?.trim().toLowerCase(); if (data.session && email !== CONTROL_EMAIL) { await supabase().auth.signOut(); message.value = 'Esta consola no admite esta cuenta.' } else if (data.session) { signedIn.value = true; await load() }; loading.value = false })
</script>

<template>
  <section v-if="!signedIn" class="login"><form @submit.prevent="signIn"><ShieldAlert /><p class="eyebrow">SPORTLEAGUES CONTROL</p><h1>Acceso de plataforma</h1><p>Entorno restringido para el operador autorizado.</p><div class="account-lock"><span>Cuenta autorizada</span><strong>{{ CONTROL_EMAIL }}</strong></div><input v-model="password" type="password" autocomplete="current-password" placeholder="Contraseña" required /><button>Ingresar de forma segura</button><span v-if="message">{{ message }}</span></form></section>
  <div v-else class="layout"><aside :class="{ open: mobileOpen }"><div class="brand"><ShieldAlert /><span>SportLeagues <small>CONTROL</small></span></div><div class="operator"><ShieldCheck /><span>Operador verificado<small>{{ CONTROL_EMAIL }}</small></span></div><nav><button v-for="item in menu" :key="item.key" :class="{ active: active === item.key }" @click="selectView(item.key)"><component :is="item.icon" />{{ item.label }}</button></nav><button class="signout" @click="signOut"><LogOut />Cerrar sesión</button></aside>
    <main><header><button class="mobile" aria-label="Abrir menú" @click="mobileOpen = !mobileOpen"><Menu /></button><div><p class="eyebrow">CONTROL PLANE · ENTORNO AISLADO</p><h1>{{ menu.find((item) => item.key === active)?.label }}</h1></div><button class="refresh" :disabled="refreshing || loading" @click="refresh"><RefreshCw :class="{ spinning: refreshing }" />{{ refreshing ? 'Actualizando' : 'Actualizar' }}</button></header>
      <section v-if="denied" class="state"><ShieldAlert /><h2>Acceso restringido</h2><p>Esta cuenta no está autorizada para la consola de plataforma.</p></section><section v-else-if="loading" class="state">Cargando control de plataforma…</section><template v-else><p v-if="message" class="notice">{{ message }}</p>
        <section v-if="filtersVisible" class="filter-bar"><div class="filter-search"><Search /><input v-model="tableQuery" placeholder="Buscar en esta vista" /></div><label class="date-input"><CalendarDays /><span>Desde</span><input v-model="fromDate" type="date" @change="quickRange = null" /></label><label class="date-input"><span>Hasta</span><input v-model="toDate" type="date" @change="quickRange = null" /></label><label v-if="statusOptions.length" class="status-select"><Filter /><select v-model="statusFilter"><option value="all">Todos los estados</option><option v-for="option in statusOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><div class="quick-filters"><button :class="{ selected: quickRange === 1 }" @click="setQuickRange(1)">Hoy</button><button :class="{ selected: quickRange === 7 }" @click="setQuickRange(7)">7 días</button><button :class="{ selected: quickRange === 30 }" @click="setQuickRange(30)">30 días</button><button class="clear-filter" @click="clearFilters"><X />Limpiar</button></div></section>

        <section v-if="active === 'overview'" class="dashboard"><div class="status-bar"><span><i></i>Operación protegida</span><p>Datos reales mediante funciones de servidor auditadas.</p></div><article v-for="card in cards" :key="card.label" class="metric"><component :is="card.icon" /><span>{{ card.label }}</span><strong>{{ card.value.toLocaleString('es-PE') }}</strong><small>{{ card.detail }}</small></article><article class="wide"><div><p class="eyebrow">VISIBILIDAD OPERATIVA</p><h2>Estado de la plataforma</h2><p>Supervisión cross-tenant sin exponer tablas globales al navegador. Cada consulta verifica la identidad autorizada en PostgreSQL.</p></div><ShieldCheck /></article><article class="signal-panel"><p class="eyebrow">SEÑALES EN VIVO</p><div v-for="signal in signals" :key="signal.label" class="signal"><div><span>{{ signal.label }}</span><small>{{ signal.note }}</small></div><strong>{{ typeof signal.value === 'number' ? signal.value.toLocaleString('es-PE') : signal.value }}</strong></div></article><article class="governance"><p class="eyebrow">GOBIERNO DE CONTROL</p><h2>Acciones disponibles</h2><ul><li><CheckCircle2 />Consultar organizaciones, actividad y solicitudes</li><li><CheckCircle2 />Administrar catálogo y precios auditados</li><li><ShieldCheck />Aplicar controles por RPC, nunca acceso directo</li></ul></article></section>
        <section v-else-if="active === 'analytics'" class="dashboard"><div class="status-bar"><span><i></i>Indicadores de crecimiento</span><p>Solo métricas calculadas desde datos operativos reales.</p></div><article v-for="item in [{ label: 'Usuarios activos ahora', value: growth?.active_users_now ?? 0, note: 'visto en los últimos 5 minutos' }, { label: 'Usuarios activos 24 h', value: growth?.active_users_24h ?? 0, note: 'señal de adopción reciente' }, { label: 'Altas en 7 días', value: growth?.new_users_7d ?? 0, note: 'nuevos perfiles registrados' }, { label: 'Clientes nuevos en 30 días', value: growth?.new_tenants_30d ?? 0, note: 'organizaciones creadas' }, { label: 'Interés comercial 30 días', value: growth?.plan_requests_30d ?? 0, note: 'solicitudes de plan' }, { label: 'Errores de cliente 24 h', value: growth?.client_errors_24h ?? 0, note: 'señal para priorizar calidad' }]" :key="item.label" class="metric"><BarChart3 /><span>{{ item.label }}</span><strong>{{ item.value.toLocaleString('es-PE') }}</strong><small>{{ item.note }}</small></article><article class="wide"><div><p class="eyebrow">LECTURA DE OPORTUNIDADES</p><h2>Adopción, demanda y calidad operativa</h2><p>Prioriza clientes nuevos y solicitudes de plan, valida su uso con actividad reciente y reduce fricción atendiendo errores repetidos.</p></div><BarChart3 /></article></section>
        <section v-else-if="active === 'tenants'" class="panel"><div class="panel-heading"><div><p class="eyebrow">DIRECTORIO</p><h2>Organizaciones</h2><p>{{ filteredTenants.length }} organizaciones con los filtros actuales.</p></div></div><div class="table"><div class="row head"><span>Nombre</span><span>Plan</span><span>Quinielas</span><span>Participantes</span></div><div v-for="tenant in filteredTenants" :key="tenant.tenant_id" class="row"><span>{{ tenant.name }}</span><span class="pill">{{ tenant.plan_code.toUpperCase() }}</span><span>{{ tenant.pools }}</span><span>{{ tenant.participants }}</span></div><p v-if="!filteredTenants.length" class="empty">No se encontraron organizaciones con los filtros actuales.</p></div></section>
        <section v-else-if="active === 'users'" class="panel"><div class="panel-heading"><div><p class="eyebrow">DIRECTORIO PRIVADO</p><h2>Usuarios</h2><p>Datos minimizados: identidad, membresías y participación; nunca correos de Auth.</p></div></div><div class="table"><div class="row head"><span>Usuario</span><span>Membresías</span><span>Quinielas</span><span>Registro</span></div><div v-for="user in filteredUsers" :key="user.profile_id" class="row"><span>{{ user.display_name }}</span><span>{{ user.memberships }}</span><span>{{ user.pools }}</span><span>{{ new Date(user.created_at).toLocaleDateString('es-PE') }}</span></div><p v-if="!filteredUsers.length" class="empty">No hay usuarios con los filtros actuales.</p></div></section>
        <section v-else-if="active === 'sports'" class="panel"><div class="panel-heading"><div><p class="eyebrow">OPERACIÓN DEPORTIVA</p><h2>Ligas, torneos y partidos</h2><p>Vista global de próximos encuentros, en vivo y resultados publicados.</p></div></div><div class="table"><div class="sport-row head"><span>Cliente · torneo</span><span>Partido</span><span>Inicio</span><span>Estado</span><span>Resultado</span></div><div v-for="match in filteredSports" :key="match.match_id" class="sport-row"><span>{{ match.tenant_name }} · {{ match.tournament_name }}</span><span>{{ match.home_team }} — {{ match.away_team }}</span><span>{{ new Date(match.starts_at).toLocaleString('es-PE', { dateStyle: 'short', timeStyle: 'short' }) }}</span><span class="pill">{{ match.status }}</span><span>{{ match.result ?? 'Pendiente' }}</span></div><p v-if="!filteredSports.length" class="empty">No hay partidos con los filtros actuales.</p></div></section>
        <section v-else-if="active === 'monitor'" class="dashboard"><article v-for="item in [{ label: 'Usuarios en vivo', value: growth?.active_users_now ?? 0 }, { label: 'Partidos en vivo', value: monitor?.matches_live ?? 0 }, { label: 'Próximos 24 h', value: monitor?.matches_next_24h ?? 0 }, { label: 'Fallos de proveedor 24 h', value: monitor?.catalog_jobs_failed_24h ?? 0 }]" :key="item.label" class="metric"><Radio /><span>{{ item.label }}</span><strong>{{ item.value.toLocaleString('es-PE') }}</strong><small>dato operativo actual</small></article><article class="wide"><div><p class="eyebrow">SINCRONIZACIÓN</p><h2>{{ monitor?.fixture_sync_events_24h ?? 0 }} eventos de fixtures en 24 h</h2><p>Monitor de disponibilidad y actividad, sin revelar payloads de proveedor ni secretos.</p></div><Activity /></article><article class="panel activity-panel"><p class="eyebrow">USUARIOS ACTIVOS</p><div v-for="user in filteredLiveUsers" :key="`${user.display_name}-${user.last_seen_at}`" class="activity-item"><div><strong>{{ user.display_name }}</strong><small>{{ user.route ?? 'Ruta no disponible' }} · {{ user.events_24h }} eventos en 24 h</small></div><time>{{ new Date(user.last_seen_at).toLocaleString('es-PE', { timeStyle: 'short' }) }}</time></div><p v-if="!filteredLiveUsers.length" class="empty">No hay usuarios en vivo con los filtros actuales.</p></article><article class="panel activity-panel"><p class="eyebrow">BITÁCORA RECIENTE</p><div v-for="event in filteredActivity" :key="`${event.source}-${event.action}-${event.created_at}`" class="activity-item"><div><strong>{{ event.action }}</strong><small>{{ event.tenant_name ?? 'Plataforma' }} · {{ event.entity_type }}</small></div><time>{{ new Date(event.created_at).toLocaleString('es-PE', { dateStyle: 'short', timeStyle: 'short' }) }}</time></div><p v-if="!filteredActivity.length" class="empty">No hay eventos con los filtros actuales.</p></article></section>
        <section v-else-if="active === 'errors'" class="panel"><div class="panel-heading"><div><p class="eyebrow">CALIDAD DE PLATAFORMA</p><h2>Errores y logs de cliente</h2><p>Eventos anonimizados y agrupados; no se almacenan secretos, tokens, correos ni trazas completas.</p></div></div><div class="table"><div class="error-row head"><span>Tipo</span><span>Evento</span><span>Ruta</span><span>Ocurrencias</span><span>Último reporte</span></div><div v-for="error in filteredErrors" :key="`${error.kind}-${error.name}-${error.message}-${error.route}`" class="error-row"><span class="pill">{{ error.kind }}</span><span><strong>{{ error.name }}</strong><small>{{ error.message }}</small></span><span>{{ error.route ?? '—' }}</span><span>{{ error.occurrences }}</span><span>{{ new Date(error.latest_at).toLocaleString('es-PE', { dateStyle: 'short', timeStyle: 'short' }) }}</span></div><p v-if="!filteredErrors.length" class="empty">No hay errores con los filtros actuales.</p></div></section>
        <section v-else-if="active === 'requests'" class="panel"><div class="panel-heading"><div><p class="eyebrow">REVISIÓN OPERATIVA</p><h2>Solicitudes de plan</h2><p>Seguimiento manual de cambios de plan; no realiza cobros.</p></div></div><div class="table"><div class="row head"><span>Organización</span><span>Oferta</span><span>Estado</span><span>Fecha</span></div><div v-for="request in filteredRequests" :key="request.id" class="row"><span>{{ request.tenant_name }}</span><span>{{ request.offer_code }}</span><span class="pill">{{ request.status }}</span><span>{{ new Date(request.requested_at).toLocaleDateString('es-PE') }}</span></div><p v-if="!filteredRequests.length" class="empty">No hay solicitudes con los filtros actuales.</p></div></section>
        <section v-else class="panel"><div class="panel-heading"><div><p class="eyebrow">CONFIGURACIÓN COMERCIAL</p><h2>Catálogo y precios</h2><p>Los cambios se validan en el servidor y quedan en la bitácora administrativa.</p></div></div><article v-for="offer in offers" :key="offer.offer_code" class="offer"><strong>{{ offer.offer_code }}</strong><label>Precio menor<input v-model.number="offer.price_minor" type="number" min="0" /></label><label>Moneda<input v-model="offer.currency" maxlength="3" /></label><label>Periodo<select v-model="offer.billing_period"><option value="month">Mes</option><option value="year">Año</option><option value="one_time">Único</option></select></label><button :disabled="saving === offer.offer_code" @click="saveOffer(offer)">{{ saving === offer.offer_code ? 'Guardando…' : 'Guardar cambio' }}</button></article></section>
      </template></main></div>
</template>
